f.rqSend=async()=>{const t=$('#rt').value,q={sid:me.id,name:me.name,roll:me.roll,bid:me.bid,type:t,h:['topic','recheck'].includes(t)?'t':'a',d:$('#rd').value.trim(),st:'new',rp:'',t:Date.now()};
if(t=='leave'){q.from=$('#rf').value;q.to=$('#re').value||q.from;if(!q.from)return alert('Choose the leave date')}
else if(t=='subject'){q.nv=$('#rg').value;q.old=me.grp||''}
else if(t=='school'){q.nv=$('#rs').value.trim();q.old=me.school||'';if(!q.nv)return alert('Write the new school/college name')}
else if(!q.d)return alert('Write the details');
await addDoc(collection(db,'rq'),q);$('#rd').value='';alert('Request sent');rqShow()};
async function rqShow(){try{const L=(await snap('rq',where('sid','==',me.id))).sort((a,b)=>b.t-a.t);$('#rql').innerHTML=L.map(q=>{const z=RQ_[q.st]||RQ_.new;return `<div class="li" style="display:block"><b>${tl(RT[q.type])}</b> <b class="${z[1]}">${tl(z[0])}</b><br><span class="mut">${rqTxt(q)} · ${new Date(q.t).toLocaleDateString()}</span>${q.rp?`<br><b>Reply:</b> ${esc(q.rp)}`:''}</div>`}).join('')||'<p class="mut">No requests yet.</p>'}catch(e){}}
let RQL=[];
V.rq=async()=>{RQL=me.role=='teacher'?(await Promise.all((me.bids||[]).map(b=>snap('rq',where('bid','==',b),where('h','==','t'))))).flat():await snap('rq');RQL.sort((a,b)=>b.t-a.t);
await Promise.all(RQL.filter(q=>q.st=='new').map(q=>updateDoc(doc(db,'rq',q.id),{st:'seen'}).then(()=>{q.st='seen'})));
return RQL.map(q=>{const z=RQ_[q.st]||RQ_.new,done=q.st=='approved'||q.st=='rejected';return `<div class="card"><b>${esc(q.name)}</b> <span class="mut">Roll ${q.roll}</span><br><b>${tl(RT[q.type])}</b> <b class="${z[1]}">${tl(z[0])}</b><p class="mut">${rqTxt(q)}</p>${done?(q.rp?`<p><b>Reply:</b> ${esc(q.rp)}</p>`:''):`<input id="rr${q.id}" placeholder="Reply (optional)"><button class="pri" onclick="f.rqAct('${q.id}',true)">Approve</button> <button onclick="f.rqAct('${q.id}',false)">Reject</button>`}</div>`}).join('')||'<div class="card"><p class="mut">No requests yet.</p></div>'};
f.rqAct=async(id,ok)=>{const q=RQL.find(x=>x.id==id),rp=$('#rr'+id).value.trim(),u=U.find(x=>x.id==q.sid)||{};
if(ok&&me.role=='admin'){if(q.type=='subject')await updateDoc(doc(db,'users',q.sid),{grp:q.nv});if(q.type=='school')await updateDoc(doc(db,'users',q.sid),{school:q.nv});
if(q.type=='leave'){const ds=[];for(let d=new Date(q.from);d<=new Date(q.to)&&ds.length<31;d.setDate(d.getDate()+1))ds.push(d.toISOString().slice(0,10));await updateDoc(doc(db,'users',q.sid),{lv:[...new Set([...(u.lv||[]),...ds])]})}}
await updateDoc(doc(db,'rq',id),{st:ok?'approved':'rejected',rp});nt(q.sid,'Request '+(ok?'approved':'rejected')+': '+RT[q.type]);render()};
V.db=async()=>{const m=T().slice(0,7),A_=U.filter(x=>x.active!==false),[P,Q]=await Promise.all([snap('pay',where('m','==',m)),snap('rq')]),AD=await Promise.all(B.map(b=>getDoc(doc(db,'att',b.id+'_'+T()))));
let pr=0;const ab=[];AD.forEach((d,i)=>{if(!d.exists())return;const x=d.data();A_.filter(z=>z.bid==B[i].id).forEach(z=>{if(x.A.includes(z.id))ab.push(z);else if(!x.E.includes(z.id))pr++})});
const due=A_.filter(z=>z.fee&&P.filter(p=>p.sid==z.id).reduce((a,p)=>a+p.amt,0)<z.fee).length,pend=Q.filter(q=>q.st=='new'||q.st=='seen').length,tile=(l,v,t)=>`<div class="card" style="margin:0" onclick="S.tab='${t}';f.r()"><div class="mut">${l}</div><b style="font-size:26px">${v}</b></div>`;
return `<div class="card"><div class="rings">${ring((pr+ab.length)?pr/(pr+ab.length)*100:null,'Attendance today','#1d7a4c')}${(t=>ring(t?(t-due)/t*100:null,'Fees paid','#2f80ed'))(A_.filter(z=>z.fee).length)}</div></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">${tile('Total students',A_.length,'stu')}${tile('Present today',pr,'att')}${tile('Absent today',ab.length,'att')}${tile('Fees due this month',due,'fee')}${tile('Pending requests',pend,'rq')}${tile('Teachers',TC.filter(x=>x.active!==false).length,'tch')}</div>
<div class="card"><h3>Today's absent</h3>${ab.map(z=>`<div class="li"><span>${esc(z.name)}<br><span class="mut">${esc((B.find(b=>b.id==z.bid)||{}).name)}</span></span><span><a href="tel:${esc(z.gphone||'')}">${esc(z.gphone||'–')}</a> ${absBtns(z,T())}</span></div>`).join('')||'<p class="mut">No absent saved for today.</p>'}</div>`};
Object.assign(BN,{"Dashboard":"ড্যাশবোর্ড","Requests":"অনুরোধ","My requests":"আমার অনুরোধ","Details / reason":"বিস্তারিত / কারণ","New school / college name":"নতুন স্কুল / কলেজের নাম","Send request":"অনুরোধ পাঠান","Reply (optional)":"উত্তর (ঐচ্ছিক)","Approve":"অনুমোদন করুন","Reject":"বাতিল করুন","Reply:":"উত্তর:","Approved":"অনুমোদিত","Rejected":"প্রত্যাখ্যাত","Not seen yet":"এখনো দেখা হয়নি","Seen – awaiting decision":"দেখা হয়েছে – সিদ্ধান্তের অপেক্ষায়","Topic review":"টপিক রিভিউ","Recheck":"রিচেক","Leave application":"ছুটির আবেদন","Change subject/group":"বিষয়/গ্রুপ পরিবর্তন","Change school/college":"স্কুল/কলেজ পরিবর্তন","No requests yet.":"এখনো কোনো অনুরোধ নেই।","Total students":"মোট ছাত্র","Present today":"আজ উপস্থিত","Absent today":"আজ অনুপস্থিত","Fees due this month":"এই মাসে বাকি ফি","Pending requests":"অপেক্ষমাণ অনুরোধ","Today's absent":"আজকের অনুপস্থিত","No absent saved for today.":"আজকের জন্য কোনো অনুপস্থিত সংরক্ষিত নেই।","Request sent":"অনুরোধ পাঠানো হয়েছে","Group (SSC/HSC only)":"গ্রুপ (শুধু SSC/HSC)"});

const ring=(v,l,c)=>{const p=v==null?0:Math.max(0,Math.min(100,v)),R=34,C=2*Math.PI*R;return `<div style="text-align:center"><svg viewBox="0 0 84 84" width="92" height="92"><circle cx="42" cy="42" r="${R}" fill="none" stroke="var(--line)" stroke-width="9"/><circle cx="42" cy="42" r="${R}" fill="none" stroke="${c}" stroke-width="9" stroke-linecap="round" stroke-dasharray="${(p/100*C).toFixed(1)} ${C.toFixed(1)}" transform="rotate(-90 42 42)"/><text x="42" y="47" text-anchor="middle" font-size="16" font-weight="700" fill="var(--ink)">${v==null?'–':Math.round(v)+'%'}</text></svg><div class="mut">${l}</div></div>`};
