const profHtml=()=>`<div class="card" style="text-align:center">${av(me,84)}<h2 style="margin:8px 0 0">${esc(me.name)}</h2><p class="mut">${{admin:'Admin',teacher:'Teacher',student:'Student'}[me.role]}${me.roll?' · Roll '+me.roll:''}</p><label class="pbtn">Change photo<input type="file" accept="image/*" hidden onchange="f.pic(this.files[0])"></label></div>
<div class="card"><h3>Blood group</h3><div class="rings" style="grid-template-columns:repeat(4,1fr)">${['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(v=>`<button class="${me.bg==v?'pri':''}" onclick="f.bgSet('${v}')">${v}</button>`).join('')}</div><p class="mut">${me.bg?'Saved: '+me.bg:'Tap your blood group. It is saved at once.'}</p></div><div class="card"><h3>My information</h3><input id="pnm" placeholder="Full name" value="${esc(me.name||'')}">${me.nick?`<p class="mut">Nickname: <b>${esc(me.nick)}</b> (only the admin can change it)</p>`:''}<p class="mut">After a name change you can still log in with your email or your old name.</p><input id="pp" placeholder="Phone" value="${esc(me.phone||'')}"><input id="pa2" placeholder="Present address" value="${esc(me.addr||'')}">${me.role=='student'?`<input id="pg" placeholder="Guardian name" value="${esc(me.gname||'')}"><input id="pgp" placeholder="Guardian phone" value="${esc(me.gphone||'')}"><input id="pge" type="email" placeholder="Guardian email (for result mails)" value="${esc(me.gem||'')}"><p class="mut">School: ${esc(me.school||'–')} · Group: ${esc(me.grp||'–')}. To change these, send a request.</p>`:''}<button class="pri" onclick="f.saveP()">Save</button></div>
${me.role=='admin'&&!me.co?`<div class="card"><h3>Login with email</h3><p class="mut">You can log in with your name or this email.</p><input id="pem" type="email" placeholder="Email"><button onclick="f.adminMail()">Save</button></div>`:''}<div class="card"><h3>Change password</h3><input id="pw0" type="password" placeholder="Current password" autocomplete="current-password"><input id="pw1" type="password" placeholder="New password (min 6)" autocomplete="new-password"><button class="pri" onclick="f.pw()">Save password</button><p class="mut" id="pwm"></p></div>`;
