const chrome=(items,cur,fn)=>`<div class="bnd" role="link" aria-label="Dashboard" onclick="${fn(items[0][0])};f.mn(0)"><img src="logo.jpg" alt=""><div><b>${esc(INST.name||'Rise Edge Academy')}</b><small>Learn · Grow · Reach Higher</small></div></div><div class="top"><button class="ham" onclick="f.mn(1)">☰</button><b class="tt">${(items.find(x=>x[0]==cur)||['',''])[1]}</b><div class="gs"><input id="gs" placeholder="${me.role=='student'?'Search pages...':'Search students, teachers, batches...'}" oninput="f.gs()" autocomplete="off"><div id="gsr" hidden></div></div><button class="bell" onclick="f.bell()">🔔<i id="bdg" hidden></i></button><a class="who" onclick="${fn('pf')};f.mn(0)">${av(me,36)}<span><b>${esc(me.name)}</b><small>${{admin:'Admin',teacher:'Teacher',student:'Student'}[me.role]}</small></span></a></div><div id="ov" onclick="f.mn(0)"></div><nav id="sd"><div class="br" style="cursor:pointer" onclick="${fn(items[0][0])};f.mn(0)"><img src="logo.jpg" alt=""><div><b>RISE EDGE</b><span>ACADEMY</span><small>Learn · Grow · Reach Higher</small></div></div>${items.map(x=>`<a class="${x[0]==cur?'on':''}" onclick="${fn(x[0])};f.mn(0)">${x[1]}</a>`).join('')}<a onclick="f.out()">Logout</a></nav>${setTimeout(()=>bellCount(),60)&&''}`;
