const showPg=()=>document.querySelectorAll('[data-pg]').forEach(e=>e.hidden=e.dataset.pg!=S.pg);
const flv=async(bs,kind,ttl)=>{if(!S.bid)return nob;const L=(await snap('fl',where('bid','==',S.bid),where('kind','==',kind))).sort((a,b)=>b.t-a.t);
return `${bs}<div class="card"><h3>Upload</h3><input id="ft" placeholder="Title"><input id="fk" placeholder="Link (Google Drive etc.), or choose a file below"><input id="ff" type="file" accept="application/pdf,image/*"><p class="mut">File max 700 KB. For bigger files use a link.</p><button class="pri" onclick="f.up('${kind}')">Upload</button></div><div class="card"><h3>${ttl}</h3>${L.map(x=>`<div class="li"><span>${esc(x.title)}<br><span class="mut">${new Date(x.t).toLocaleDateString()}</span></span><span><button onclick="f.dl('${x.id}')">Open</button> <button onclick="f.fdel('${x.id}')">Delete</button></span></div>`).join('')||'<p class="mut">Nothing yet.</p>'}</div>`};
V.sg=bs=>flv(bs,'sug','Suggestions');V.sl=bs=>flv(bs,'sol','Exam solutions');
f.up=async kind=>{const t=$('#ft').value.trim(),lk=$('#fk').value.trim(),fl=$('#ff').files[0];if(!t||(!lk&&!fl))return alert('Add a title and a link or a file');if(fl&&fl.size>700*1024)return alert('File is too big (max 700 KB). Use a link instead.');
const r=await addDoc(collection(db,'fl'),{bid:S.bid,kind,title:t,link:lk,name:fl?fl.name:'',t:Date.now()});
if(fl&&!lk){const d=await new Promise(o=>{const rd=new FileReader();rd.onload=()=>o(rd.result);rd.readAsDataURL(fl)});await setDoc(doc(db,'fd',r.id),{bid:S.bid,data:d})}
nt('batch',(kind=='sug'?'New suggestion: ':'New exam solution: ')+t,S.bid);alert('Saved');render()};
f.dl=async id=>{const m=(await getDoc(doc(db,'fl',id))).data();if(m.link)return void window.open(m.link,'_blank');const d=(await getDoc(doc(db,'fd',id))).data(),a=document.createElement('a');a.href=d.data;a.download=m.name||'file';a.click()};
f.fdel=async id=>{if(!confirm('Delete?'))return;await deleteDoc(doc(db,'fd',id)).catch(()=>{});await deleteDoc(doc(db,'fl',id));render()};
async function fileShow(){try{const L=(await snap('fl',where('bid','==',me.bid))).sort((a,b)=>b.t-a.t),h=k=>L.filter(x=>x.kind==k).map(x=>`<div class="li"><span>${esc(x.title)}<br><span class="mut">${new Date(x.t).toLocaleDateString()}</span></span><button onclick="f.dl('${x.id}')">Download</button></div>`).join('')||'<p class="mut">Nothing yet.</p>';$('#sgl').innerHTML=h('sug');$('#sll').innerHTML=h('sol')}catch(e){}}
const pend=p=>p.sel.filter(i=>!p.ok.includes(i));
V.sy=async bs=>{if(!S.bid)return nob;const SY=await snap('sy',where('bid','==',S.bid)),SP=await snap('sp',where('bid','==',S.bid));S.SY=SY;S.SP=SP;
return `${bs}<div class="card"><h3>Add subject syllabus</h3><input id="ys" placeholder="Subject"><input id="yb" placeholder="NCTB textbook name"><textarea id="yt" rows="5" placeholder="Topics / chapters, one per line"></textarea><button class="pri" onclick="f.yAdd()">Add</button></div>
${SP.filter(p=>pend(p).length&&SY.find(y=>y.id==p.syid)).map(p=>{const y=SY.find(z=>z.id==p.syid),st=U.find(z=>z.id==p.sid)||{};return `<div class="card"><b>${esc(st.name)}</b> · ${esc(y.subj)}<p class="mut">Untick topics that are not really finished, then Approve.</p>${pend(p).map(i=>`<label class="li"><span>${esc(y.tp[i])}</span><input type="checkbox" checked data-p="${p.id}" value="${i}"></label>`).join('')}<button class="pri" onclick="f.yOk('${p.id}')">Approve</button></div>`}).join('')}
<div class="card"><h3>Subjects</h3>${SY.map(y=>{const t=act().length*y.tp.length,d=SP.filter(p=>p.syid==y.id).reduce((a,p)=>a+p.ok.length,0);return `<div class="li"><span>${esc(y.subj)}<br><span class="mut">${esc(y.book||'')} · ${y.tp.length} topics · ${t?Math.round(d/t*100):0}% done</span></span><button onclick="f.yDel('${y.id}')">Delete</button></div>`}).join('')||'<p class="mut">No syllabus yet.</p>'}</div>`};
f.yAdd=async()=>{const tp=$('#yt').value.split('\n').map(x=>x.trim()).filter(Boolean),sj=$('#ys').value.trim();if(!sj||!tp.length)return alert('Add the subject and topics');await addDoc(collection(db,'sy'),{bid:S.bid,subj:sj,book:$('#yb').value.trim(),tp});render()};
f.yDel=async id=>{if(confirm('Delete?')){await deleteDoc(doc(db,'sy',id));render()}};
f.yOk=async pid=>{const p=S.SP.find(x=>x.id==pid),y=S.SY.find(z=>z.id==p.syid),bx=[...document.querySelectorAll('input[data-p="'+pid+'"]')],yes=bx.filter(b=>b.checked).map(b=>+b.value),no=bx.filter(b=>!b.checked).map(b=>+b.value);
await updateDoc(doc(db,'sp',pid),{ok:[...new Set([...p.ok,...yes])],sel:p.sel.filter(i=>!no.includes(i)),rej:[...new Set([...(p.rej||[]),...no])]});nt(p.sid,'Syllabus checked: '+y.subj+(no.length?' ('+no.length+' topic(s) not approved)':' approved'));render()};
async function syShow0(){try{const SY=await snap('sy',where('bid','==',me.bid)),SP=await snap('sp',where('sid','==',me.id));S.msp=SP;
$('#syl').innerHTML=SY.map(y=>{const p=SP.find(z=>z.syid==y.id)||{sel:[],ok:[],rej:[]},pc=Math.round(p.ok.length/y.tp.length*100);
return `<div style="border:1px solid var(--line);border-radius:14px;padding:12px;margin:0 0 12px"><b>${esc(y.subj)}</b> <span class="mut">${esc(y.book||'')}</span><div style="height:8px;border-radius:99px;background:var(--line);margin:8px 0"><div style="height:8px;width:${pc}%;border-radius:99px;background:var(--ok)"></div></div><p class="mut">${p.ok.length} / ${y.tp.length} (${pc}%)</p>${y.tp.map((t,i)=>{const ok=p.ok.includes(i),wt=p.sel.includes(i)&&!ok,rj=(p.rej||[]).includes(i)&&!p.sel.includes(i);return `<label class="li"><span>${esc(t)}${rj?'<br><span class="bad">Not approved, select again</span>':''}</span>${ok?'<b class="ok">Approved</b>':wt?'<b class="warn">Waiting</b>':`<input type="checkbox" data-y="${y.id}" value="${i}">`}</label>`}).join('')}<button class="pri" onclick="f.yPost('${y.id}')">Send for approval</button></div>`}).join('')||'<p class="mut">No syllabus yet.</p>'}catch(e){}}
f.yPost=async yid=>{const p=S.msp.find(z=>z.syid==yid)||{sel:[],ok:[],rej:[]},c=[...document.querySelectorAll('input[data-y="'+yid+'"]')].filter(b=>b.checked).map(b=>+b.value);if(!c.length)return alert('Tick the finished topics first');
await setDoc(doc(db,'sp',me.id+'_'+yid),{sid:me.id,bid:me.bid,syid:yid,sel:[...new Set([...p.sel,...c])],ok:p.ok,rej:(p.rej||[]).filter(i=>!c.includes(i))});alert('Sent');syShow()};
