const ZORD=['বাংলা ১ম পত্র','বাংলা ২য় পত্র','English 1st Paper','English 2nd Paper','গণিত','সাধারণ গণিত','বিজ্ঞান','সাধারণ বিজ্ঞান','বাংলাদেশ ও বিশ্বপরিচয়','ইসলাম ও নৈতিক শিক্ষা'];
function ZL(cls,grp,sd){const R=ZL0(cls,grp,sd),c=+cls;if(!c)return R;const ex=[['বাংলা ১ম পত্র',ZB1[c]],['English 1st Paper',ZE1[c]],['ইসলাম ও নৈতিক শিক্ষা',ZIS[c]]].filter(e=>e[1]).map(([s,t])=>({s,t}));const all=[...ex,...R],rk=s=>{const i=ZORD.indexOf(s);return i<0?99:i};return all.map((x,i)=>[x,i]).sort((a,b)=>rk(a[0].s)-rk(b[0].s)||a[1]-b[1]).map(a=>a[0])}
function ZL0(cls,grp,sd){cls=+cls;let L=[];if(ZNC[cls])L=Object.entries(ZNC[cls]);else if(cls==9||cls==10){L=Object.entries(Z910);const gs=grp&&ZG[grp]?[grp]:Object.keys(ZG),seen=new Set();gs.forEach(g=>Object.entries(ZG[g]).forEach(e=>{if(!seen.has(e[0])){seen.add(e[0]);L.push(e)}}))}
if(cls)L=[...L,['বাংলা ২য় পত্র',ZB2],['English 2nd Paper',ZE2]];return [...L.map(([s,t])=>({s,t})),...((sd&&sd.cx)||[]).filter(x=>!x.g||!grp||x.g==grp)]}
const ZCL={6:'৬ষ্ঠ',7:'৭ম',8:'৮ম',9:'৯ম',10:'১০ম'},ZGP={Science:'বিজ্ঞান',Commerce:'ব্যবসায় শিক্ষা',Arts:'মানবিক'},bd=n=>String(n).replace(/\d/g,c=>'০১২৩৪৫৬৭৮৯'[c]);
const ZMSG='এখানে শুধুমাত্র সেই টপিক select করবা যেটাতে তোমার আত্মবিশ্বাস আছে যে তুমি পরীক্ষায় answer করতে পারবা';
const clsSel=(id,v)=>`<select id="${id}"><option value="">Class</option>${[6,7,8,9,10,11,12].map(c=>`<option value="${c}" ${+v==c?'selected':''}>Class ${c}</option>`).join('')}</select>`;

// ---- fees: same for all (default 2500), admin can change per batch or per student ----
function fe(s){const b=B.find(x=>x.id==s.bid)||{};return +s.fo>0?+s.fo:+b.fee>0?+b.fee:(+INST.fee||2500)}
const ofee=V.fee;V.fee=async bs=>{const h=await ofee(bs);if(me.role!='admin'||!S.bid)return h;const b=B.find(x=>x.id==S.bid)||{},L=act();
return h+`<div class="card"><h3>Fee settings</h3><p class="mut">Everyone pays the default fee unless you set a batch fee or a personal fee.</p><label class="mut">Default fee (all students)</label><input id="zfd" type="number" value="${+INST.fee||2500}"><button onclick="f.zFee('d')">Save default</button><hr><label class="mut">Fee for this batch (${esc(b.name||'')}) – blank = default</label><input id="zfb" type="number" value="${b.fee||''}"><button onclick="f.zFee('b')">Save batch fee</button><hr><label class="mut">Personal fee for one student – blank = remove</label><select id="zfs">${L.map(s=>`<option value="${s.id}">${esc(s.name)} · ৳${s.fee}${+s.fo>0?' (personal)':''}</option>`).join('')}</select><input id="zfi" type="number" placeholder="Amount"><button onclick="f.zFee('s')">Save personal fee</button></div>`};
f.zFee=async k=>{try{if(k=='d'){const v=+$('#zfd').value;if(!(v>0))return alert('Enter the amount');INST={...INST,fee:v};await setDoc(doc(db,'config','inst'),INST)}
else if(k=='b'){const v=+$('#zfb').value||0;await updateDoc(doc(db,'batches',S.bid),{fee:v})}
else{const id=$('#zfs').value,v=+$('#zfi').value||0;await updateDoc(doc(db,'users',id),{fo:v})}alert('Saved');render()}catch(e){alert(e.message)}};
f.si=async()=>{INST={...INST,name:$('#in').value,owner:$('#io').value,phone:$('#ip').value};await setDoc(doc(db,'config','inst'),INST);alert('Saved')};

// ---- full profile popup (student / teacher) ----
