// ---- syllabus: teacher/admin tick finished topics; see student confidence ----
V.sy=async bs=>{if(!S.bid)return nob;const b=B.find(x=>x.id==S.bid);let d={};try{const q=await getDoc(doc(db,'sd',S.bid));d=q.exists()?q.data():{}}catch(e){}d.done=d.done||{};d.cx=d.cx||[];S.SD=d;
let M=[];try{M=await snap('ms',where('bid','==',S.bid))}catch(e){}const g=b.grp||S.ysg||'',L=ZL(b.cls,g,d);if(!L.some(x=>x.s==S.ysj))S.ysj=(L[0]||{}).s;const y=L.find(x=>x.s==S.ysj),dn=y?(d.done[y.s]||[]):[],cf=i=>M.filter(m=>((m.c||{})[S.ysj]||[]).includes(i)).length;
return `${bs}<div class="card" ${b.grp?'hidden':''}><h3>Group</h3><select onchange="S.ysg=this.value;f.r()">${['','Science','Commerce','Arts'].map(g=>`<option value="${g}" ${(S.ysg||'')==g?'selected':''}>${g||'All groups'}</option>`).join('')}</select><p class="mut">Pick a group to see only that group's subjects and students.</p></div>${b.cls?'':`<div class="card"><b class="warn">This batch has no class set.</b><p class="mut">${me.role=='admin'?'Open Batches and choose the class to load the NCTB syllabus.':'Ask the admin to set the class of this batch.'}</p></div>`}
${L.length?`<div class="card"><h3>Subject</h3><select onchange="S.ysj=this.value;f.r()">${L.map(x=>`<option ${x.s==S.ysj?'selected':''}>${esc(x.s)}</option>`).join('')}</select><p class="mut">${dn.length} / ${y.t.length} topics finished (${y.t.length?Math.round(dn.length/y.t.length*100):0}%). Tick the topics you have finished in class – students can see this. 👍 = students confident.</p>${y.t.map((t,i)=>`<label class="li"><span>${esc(t)}${PEN(i)} <span class="mut">👍 ${cf(i)}</span></span><input type="checkbox" class="zt" value="${i}" ${dn.includes(i)?'checked':''}></label>`).join('')}<button class="pri" onclick="f.zSave()">Save</button></div>
<div class="card"><h3>Student confidence · ${esc(y.s)}</h3>${act().filter(s=>!g||s.grp==g).map(s=>{const c=((M.find(m=>m.sid==s.id)||{}).c||{})[S.ysj]||[];return `<details><summary>${esc(s.name)} · ${c.length} / ${y.t.length}</summary>${c.map(i=>`<div class="mut">✔ ${esc(y.t[i]||'')}</div>`).join('')||'<p class="mut">Nothing ticked yet.</p>'}</details>`}).join('')||'<p class="mut">No students.</p>'}</div>`:''}
<div class="card"><h3>Add extra subject</h3><input id="ys" placeholder="Subject"><select id="ysg"><option value="">All groups</option><option>Science</option><option>Commerce</option><option>Arts</option></select><textarea id="yt" rows="5" placeholder="Topics / chapters, one per line"></textarea><button onclick="f.zAdd()">Add</button>${d.cx.map((x,i)=>`<div class="li"><span>${esc(x.s)} <span class="mut">${x.t.length} topics${x.g?' · '+x.g:''}</span></span><button onclick="f.zDel(${i})">Delete</button></div>`).join('')}</div>`};
const zPut=()=>setDoc(doc(db,'sd',S.bid),{bid:S.bid,done:S.SD.done,cx:S.SD.cx},{merge:true});
f.zSave=async()=>{S.SD.done[S.ysj]=[...document.querySelectorAll('.zt')].filter(b=>b.checked).map(b=>+b.value);await zPut();nt('batch','Syllabus updated: '+S.ysj,S.bid);alert('Saved');render()};
f.zAdd=async()=>{const s=$('#ys').value.trim(),t=$('#yt').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!s||!t.length)return alert('Add the subject and topics');S.SD.cx.push({s,t,g:($('#ysg')||{}).value||''});await zPut();render()};
f.zDel=async i=>{if(!confirm('Delete?'))return;S.SD.cx.splice(i,1);await zPut();render()};

// ---- student side ----
let ZB={},ZD={done:{},cx:[]},ZM={c:{}};
async function zLoad(){if(!me.bid)return;const g=(c,i)=>getDoc(doc(db,c,i)).catch(()=>null),[q1,q2,q3]=await Promise.all([g('batches',me.bid),g('sd',me.bid),g('ms',me.id)]);ZB=q1&&q1.exists()?q1.data():{};ZD=q2&&q2.exists()?q2.data():{};ZD.done=ZD.done||{};ZD.cx=ZD.cx||[];ZM=q3&&q3.exists()?q3.data():{c:{}};ZM.c=ZM.c||{}}
async function student(){await zLoad();await student0();if(S.pg=='pf')return;zRq();zMsy();zYrS()}
