async function syShow(){const L=myL();$('#syl').innerHTML=L.map(y=>{const dn=ZD.done[y.s]||[],pc=y.t.length?Math.round(dn.length/y.t.length*100):0;return `<details style="border:1px solid var(--line);border-radius:14px;padding:12px;margin:0 0 12px"><summary><b>${esc(y.s)}</b> <span class="mut">${dn.length} / ${y.t.length} finished in class</span><div style="height:8px;border-radius:99px;background:var(--line);margin:8px 0"><div style="height:8px;width:${pc}%;border-radius:99px;background:var(--ok)"></div></div></summary>${y.t.map((t,i)=>`<div class="li"><span>${esc(t)}</span>${dn.includes(i)?'<b class="ok">✔ Finished</b>':'<span class="mut">Not yet</span>'}</div>`).join('')}</details>`}).join('')||'<p class="mut">No syllabus yet. Your batch class is not set.</p>'}
function zMsy(){const e=$('#msy');if(!e)return;const L=myL();e.innerHTML=`<h3>My syllabus</h3><div style="background:color-mix(in srgb,var(--acc) 18%,var(--card));border-left:5px solid var(--acc);padding:12px;border-radius:10px;margin:0 0 12px;font-weight:600">${ZMSG}</div>`+(L.map(y=>{const c=ZM.c[y.s]||[];return `<details style="border:1px solid var(--line);border-radius:14px;padding:12px;margin:0 0 10px"><summary><b>${esc(y.s)}</b> <span class="mut">${c.length} / ${y.t.length} confident</span></summary>${y.t.map((t,i)=>`<label class="li"><span>${esc(t)}</span><input type="checkbox" class="zm" data-s="${esc(y.s)}" value="${i}" ${c.includes(i)?'checked':''}></label>`).join('')}</details>`}).join('')||'<p class="mut">No syllabus yet. Your batch class is not set.</p>')+(L.length?'<button class="pri" onclick="f.zMs()">Save</button>':'')}
