function regFormOld(m=''){out(`<div class="card"><h2>Registration</h2><p class="mut">${m||'Fill the form. After the admin approves, your roll number and temporary password are sent to your email.'}</p>
<select id="rr" onchange="f.rr()"><option value="student">Student</option><option value="teacher">Teacher</option></select><input id="rn" placeholder="Full name"><input id="rnk" placeholder="Nickname (only admin can change it later)">
<div id="rs1">${clsSel('rcl','')}<input id="rsc" placeholder="School / College"><input id="rgph" type="tel" placeholder="Guardian phone"><input id="rgem" type="email" placeholder="Guardian email (optional)"><select id="rgp"><option value="">Group (SSC/HSC only)</option><option>Science</option><option>Commerce</option><option>Arts</option></select></div>
<div id="rt1" hidden><input id="rsb" placeholder="Subject you teach"><input id="rcc" placeholder="Classes you teach, e.g. 9-10"></div>
<input id="rph" type="tel" placeholder="Phone"><input id="rem" type="email" placeholder="Email (your login details will be sent here)"><input id="rad" placeholder="Present address"><button class="pri" onclick="f.regSend()">Send registration</button> <button onclick="f.regBack()">Back</button></div>`)}
f.rr=()=>{const t=$('#rr').value=='teacher';$('#rs1').hidden=t;$('#rt1').hidden=!t};
f.regBack=()=>login();
f.regSend=async()=>{const v=id=>($('#'+id).value||'').trim(),role=v('rr'),n=v('rn'),em2=v('rem');if(!n||!v('rph')||!em2.includes('@'))return alert('Please enter your name, phone and a valid email');
const d={role,name:n,nick:v('rnk'),phone:v('rph'),email:em2,addr:v('rad'),st:'pending',t:Date.now()};if(role=='student'){d.cls=v('rcl');d.school=v('rsc');d.grp=v('rgp');d.gphone=v('rgph');d.gem=v('rgem')}else{d.subject=v('rsb');d.cls=v('rcc')}
try{await addDoc(collection(db,'reg'),d);notifyReg(d);alert('Registration sent. Please wait for the admin to approve it. You will get your login details by email.');login()}catch(e){alert('Could not send: '+e.message)}};
const mailCfg=async()=>{try{const q=await getDoc(doc(db,'config','mail'));return q.exists()?q.data():{}}catch(e){return{}}};
async function sendMail0(to,name,roll,pw){const m=await mailCfg();if(!m.pk||!m.sid||!m.tid)return 'Email is not set up yet';
try{const x=await fetch('https://api.emailjs.com/api/v1.0/email/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_id:m.sid,template_id:m.tid,user_id:m.pk,template_params:{to_email:to,to_name:name,roll,password:pw,site:location.origin+location.pathname}})});return x.ok?'':'Email service said: '+(await x.text())}catch(e){return 'Network error'}}
