async function addLogin(key,ae,old){key=lk(key);if(!key||key.length>200||!ae)return;try{const r=doc(db,'login',key),q=await getDoc(r);let es=q.exists()?(q.data().es||[q.data().e].filter(Boolean)):[];es=es.filter(x=>x!=old&&x!=ae);es.push(ae);await setDoc(r,{es,e:ae})}catch(e){}}
async function rmLogin(key,ae){key=lk(key);if(!key||!ae)return;try{const r=doc(db,'login',key),q=await getDoc(r);if(!q.exists())return;const es=(q.data().es||[q.data().e]).filter(x=>x&&x!=ae);es.length?await setDoc(r,{es,e:es[es.length-1]}):await deleteDoc(r)}catch(e){}}
