// ---- optional reCAPTCHA v3 token for EmailJS ----
async function rcToken(k){if(!window.grecaptcha)await new Promise((ok,no)=>{const x=document.createElement('script');x.src='https://www.google.com/recaptcha/api.js?render='+encodeURIComponent(k);x.onload=ok;x.onerror=no;document.head.appendChild(x)});
return new Promise(ok=>grecaptcha.ready(()=>grecaptcha.execute(k,{action:'send'}).then(ok)))}
async function sendMail(to,name,roll,pw){const m=await mailCfg();if(!m.pk||!m.sid||!m.tid)return 'Email is not set up yet';
try{const p={to_email:to,to_name:name,roll,password:pw,site:location.origin+location.pathname};if(m.rc)p['g-recaptcha-response']=await rcToken(m.rc);
const x=await fetch('https://api.emailjs.com/api/v1.0/email/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_id:m.sid,template_id:m.tid,user_id:m.pk,template_params:p})});return x.ok?'':'Email service said: '+(await x.text())}catch(e){return 'Network error'}}
