// ---- dashboard look: stat cards, donuts, search, bell ----
const PAL=['#2563eb','#10b981','#f59e0b','#8b5cf6','#06b6d4','#ec4899','#ef4444','#64748b'];
const ago=t=>{const m=Math.round((Date.now()-t)/6e4);return m<1?'just now':m<60?m+' min ago':m<1440?Math.round(m/60)+' h ago':Math.round(m/1440)+' d ago'};
const donut=(parts,top,sub)=>{const R=42,C=2*Math.PI*R,tot=parts.reduce((a,p)=>a+p.v,0)||1;let off=0;return `<svg viewBox="0 0 110 110" width="140" height="140"><circle cx="55" cy="55" r="${R}" fill="none" stroke="var(--line)" stroke-width="14"/>${parts.map(p=>{const l=p.v/tot*C,e=`<circle cx="55" cy="55" r="${R}" fill="none" stroke="${p.c}" stroke-width="14" stroke-dasharray="${l.toFixed(1)} ${(C-l).toFixed(1)}" stroke-dashoffset="${(-off).toFixed(1)}" transform="rotate(-90 55 55)"/>`;off+=l;return e}).join('')}<text x="55" y="54" text-anchor="middle" font-size="15" font-weight="800" fill="var(--ink)">${top}</text><text x="55" y="68" text-anchor="middle" font-size="8" fill="var(--mut)">${sub}</text></svg>`};
const sc=(ic,l,v,sub,c,t)=>`<div class="sc" style="--c:${c}" ${t?`onclick="S.tab='${t}';f.r()"`:''}><i>${ic}</i><div><div class="mut">${l}</div><b>${v}</b><div class="sub">${sub||''}</div></div></div>`;
