const ph=n=>{const d=String(n||'').replace(/\D/g,'');return d.startsWith('880')?d:d.startsWith('0')?'88'+d:d};
function gRows(e){const R=act().map(s=>{let g=0,t=0;const pt=e.subs.filter(u=>u.st=='H').map(u=>{const m=+(u.m[s.id]||0);g+=m;t+=u.total;return u.n+' '+m+'/'+u.total});return{s,g,t,pt}}),vs=[...new Set(R.filter(r=>r.t).map(r=>r.g))].sort((a,b)=>b-a);
R.forEach(r=>{r.rk=r.t?vs.indexOf(r.g)+1:0;r.txt=(INST.name||'Rise Edge Academy')+': '+r.s.name+' (Roll '+r.s.roll+') - '+e.title+': '+(r.pt.join(', ')||'no subject held')+'. Total '+r.g+'/'+r.t+(r.t?' ('+Math.round(r.g/r.t*100)+'%)':'')+(r.rk?', Rank #'+r.rk:'')+'.'});return R}
async function mail3(to,name,subject,message){const m=await mailCfg();if(!m.pk||!m.sid||!m.t2)return 'Email is not set up (Template ID 2 is missing)';
try{const p={to_email:to,to_name:name,subject,message,site:location.origin+location.pathname};if(m.rc)p['g-recaptcha-response']=await rcToken(m.rc);const x=await fetch('https://api.emailjs.com/api/v1.0/email/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_id:m.sid,template_id:m.t2,user_id:m.pk,template_params:p})});return x.ok?'':'Email service said: '+(await x.text())}catch(e){return 'Network error'}}
async function gMailAll(e){const R=gRows(e).filter(r=>r.s.gem);if(!R.length)return alert('No guardian email is saved yet. Students or guardians can add it in the student Profile.');let ok=0,er='';
for(const r of R){const x=await mail3(r.s.gem,'Guardian of '+r.s.name,'Result: '+e.title+' - '+r.s.name,'Dear Guardian, '+r.txt);if(x)er=x;else ok++;await new Promise(o=>setTimeout(o,700))}alert('Emails sent: '+ok+' / '+R.length+(er?'\nError: '+er:''))}
