// Add fee: tap a batch, choose month + amount, publish -> students of that batch see it on their dashboard / Fees page
function feeAddV(){const b0=B.find(b=>b.id==S.fb),m=S.afm||T().slice(0,7),cur=b0?BF[b0.id+'_'+m]:'',
pl=b0?Object.keys(BF).filter(k=>k.startsWith(b0.id+'_')).map(k=>[k.slice(b0.id.length+1),BF[k]]).sort((a,b)=>b[0]>a[0]?1:-1):[],
panel=b0?`<div class="card" style="margin:0 0 10px"><label class="mut">Month</label><input id="afm" type="month" value="${m}" onchange="S.afm=this.value;S.afa='';f.r()"><label class="mut">Amount (৳)</label><input id="afa" type="number" step="any" min="1" placeholder="Amount" value="${S.afa||cur||''}" oninput="S.afa=this.value"><button class="pri" onclick="f.fpub()">Publish</button>${cur?`<p class="mut">This month already has ৳${cur}. Publishing again changes it.</p>`:''}${pl.length?`<h3 style="margin-top:14px">Published</h3>`+pl.map(([mm,a])=>`<div class="li"><span><b>${mLbl(mm)}</b></span><span>৳${a} <button onclick="f.fbdel('${mm}')">Remove</button></span></div>`).join(''):''}</div>`:'';
return `<div class="card"><h3>Add fee</h3><p class="mut">Tap a batch, then choose the month and the amount. Publishing shows the fee on the dashboard of every student in that batch.</p>${B.map(b=>`<div class="li" style="cursor:pointer" onclick="f.fab('${b.id}')"><span><b>${esc(b.name)}</b><br><span class="mut">${b.cls?'Class '+esc(b.cls)+' · ':''}${U.filter(s=>s.bid==b.id&&s.active!==false).length} student(s)</span></span><span class="mut">${S.fb==b.id?'▾':'›'}</span></div>${S.fb==b.id?panel:''}`).join('')||'<p class="mut">Add a batch first.</p>'}</div>`}
f.fab=id=>{S.fb=S.fb==id?null:id;S.afa='';f.r()};
f.fpub=async()=>{const b=S.fb,m=($('#afm')||{}).value||S.afm||T().slice(0,7),a=+$('#afa').value;if(!b||me.co)return;if(!/^\d{4}-\d{2}$/.test(m))return alert('Choose the month');if(!(a>0))return alert('Enter the amount');
try{await setDoc(doc(db,'bf',b+'_'+m),{bid:b,m,amt:a,t:Date.now(),by:me.name});nt('batch','Fee published: '+mLbl(m)+' ৳'+a,b);S.afa='';alert('Published');render()}catch(e){alert(e.message)}};
f.fbdel=async m=>{if(me.co||!S.fb||!confirm('Remove this fee? The default fee will apply again.'))return;try{await deleteDoc(doc(db,'bf',S.fb+'_'+m));render()}catch(e){alert(e.message)}};
// Payment: teacher salary - pick a teacher, amount, month -> done; the teacher sees it on the dashboard
async function salV(){const m=S.sm||T().slice(0,7),TL=TC.filter(t=>t.active!==false);let P=[];try{P=await snap('sal',where('m','==',m))}catch(e){}
return `<div class="card"><h3>Add payment</h3>${TL.length?`<select id="sat">${TL.map(t=>`<option value="${t.id}">${esc(t.name)}${t.subject?' · '+esc(t.subject):''}</option>`).join('')}</select><input id="saa" type="number" step="any" min="1" placeholder="Amount"><label class="mut">Month</label><input id="sam" type="month" value="${m}"><button class="pri" onclick="f.sapay()">Payment done</button>`:'<p class="mut">Add a teacher first (Teachers tab).</p>'}</div>
<div class="card"><h3>Teacher payment status</h3><input type="month" value="${m}" onchange="S.sm=this.value;f.r()">${TL.map(t=>{const p=P.filter(x=>x.tid==t.id),sum=n2(p.reduce((a,x)=>a+x.amt,0));return `<div class="li" style="flex-wrap:wrap"><span><b>${esc(t.name)}</b><br><span class="mut">${esc(t.subject||'')}</span></span><b class="${p.length?'ok':'bad'}">${p.length?'Paid ৳'+sum:'Not paid'}</b>${p.map(x=>`<div class="mut" style="flex:1 1 100%">৳${x.amt} · ${esc(x.d||'')} <button onclick="f.sadel('${x.id}')">Delete</button></div>`).join('')}</div>`}).join('')||'<p class="mut">No teacher yet.</p>'}</div>`}
f.sapay=async()=>{if(me.co)return;const id=$('#sat').value,t=TC.find(x=>x.id==id),a=+$('#saa').value,m=$('#sam').value;if(!t)return;if(!(a>0))return alert('Enter the amount');if(!/^\d{4}-\d{2}$/.test(m))return alert('Choose the month');
try{await addDoc(collection(db,'sal'),{tid:id,name:t.name,m,amt:a,d:T(),t:Date.now(),by:me.name});nt(id,'Payment received: ৳'+a+' for '+mLbl(m));S.sm=m;alert('Payment done');render()}catch(e){alert(e.message)}};
f.sadel=async id=>{if(me.co||!confirm('Delete this payment?'))return;try{await deleteDoc(doc(db,'sal',id));render()}catch(e){alert(e.message)}};
// teacher dashboard: salary card
async function salCard(){let P=[];try{P=(await snap('sal',where('tid','==',me.id))).sort((a,b)=>b.t-a.t)}catch(e){return ''}
const m=T().slice(0,7),cur=P.filter(p=>p.m==m),sum=n2(cur.reduce((a,p)=>a+p.amt,0));
return `<div class="card"><h3>Salary</h3>${cur.length?`<b class="ok" style="font-size:18px">✔ ${mLbl(m)}: Paid ৳${sum}</b>`:`<b class="warn">${mLbl(m)}: Not paid yet</b>`}${P.slice(0,5).map(p=>`<div class="li"><span><b>${mLbl(p.m)}</b><br><span class="mut">${esc(p.d||'')}</span></span><b class="ok">৳${p.amt}</b></div>`).join('')}</div>`}
const _tdb5=V.tdb;V.tdb=async()=>{const h=await _tdb5();if(me.role!='teacher')return h;const c=await salCard(),i=h.indexOf('<div class="card" id="xbw">'),j=i<0?h.indexOf('<div class="card"><h3>My classes</h3>'):i;return j<0?h+c:h.slice(0,j)+c+h.slice(j)};
